command:
set +e
set -uo pipefail
export PATH=/opt/conda/bin:$PATH
export TMPDIR=/tmp HOME=/tmp LC_ALL=C
cd /tmp

# spawn runs task commands under bash -e; `set -uo pipefail` does not clear it (spawn#707).
#
# bwa mem vs bowtie2 --local on IDENTICAL bytes: the same 24,148,993 read pairs of SRR062634
# against the same GRCh38_full_analysis_set_plus_decoy_hla reference. Two unrelated codebases,
# one input -- the strongest check shape this project has.
#
# THE METRIC IS GATED, AND THAT IS NOT A CONVENIENCE. A naive all-mapped concordance between
# two correct aligners on a repeat-rich reference measures how they break repeat ties, not
# whether either is right: measured at 0.43 for minimap2 vs bwa where the MAPQ>=30 gated
# figure was 0.9921. So this asserts "they agree where both are confident" -- MAPQ>=30 on
# BOTH sides and positions within 5 bp. practices/cross-checks.md.
#
# MODES ARE MATCHED. bwa soft-clips; bowtie2's default end-to-end does not, which measured
# 82% where --local gave 0.9462. The bowtie2 side here was run --local for exactly that
# reason, and the index was built on bwa's own reference rather than a published one.

samtools --version | head -1
nproc | awk '{print "nproc\t"$1}'

echo "== both sides must come from the same reads: assert bwa's primary count =="
# bowtie2 reported 48,297,986 primary records = 2 x 24,148,993 pairs. If bwa's BAM does not
# carry the same primary count it is not the same input and the comparison is meaningless.
samtools flagstat -@ "$(nproc)" aln.sorted.bam > /tmp/flagstat.txt 2>&1
FRC=$?
test "$FRC" = "0" || { cat /tmp/flagstat.txt; echo "FAIL: flagstat exited $FRC"; exit 1; }
BWAPRIM=$(awk '/primary$/{print $1; exit}' /tmp/flagstat.txt)
echo "bwa_primary	$BWAPRIM"
echo "bowtie2_primary	48297986"
test "$BWAPRIM" = "48297986" || { echo "FAIL: bwa has $BWAPRIM primary records, bowtie2 had 48297986 -- different inputs"; exit 1; }
echo "same_input	both tools aligned the same 48,297,986 primary records"

# ---------------------------------------------------------------- extract both sides
# -F 0x900 drops secondary (0x100) and supplementary (0x800) so only primaries remain; -q 30
# is the confidence gate. Sorted by name then position, with on-disk compression so the sort
# stays inside tmpfs.
echo "== bwa: primary, MAPQ>=30 =="
samtools view -@ "$(nproc)" -F 0x900 -q 30 aln.sorted.bam \
  | awk -F'\t' 'BEGIN{OFS="\t"} {print $1,$3,$4}' \
  | sort -t$'\t' -k1,1 -k3,3n --compress-program=gzip -S 6G -T /tmp > /tmp/bwa.tsv
test "${PIPESTATUS[0]}" = "0" || { echo "FAIL: samtools view failed"; exit 1; }
BWAN=$(wc -l < /tmp/bwa.tsv)
echo "bwa_hiq_records	$BWAN"

echo "== bowtie2: primary, MAPQ>=30 (pre-filtered when the clock ran) =="
zcat bt2_hiq.tsv.gz \
  | awk -F'\t' 'BEGIN{OFS="\t"} {print $1,$2,$3}' \
  | sort -t$'\t' -k1,1 -k3,3n --compress-program=gzip -S 6G -T /tmp > /tmp/bt2.tsv
test "${PIPESTATUS[0]}" = "0" || { echo "FAIL: zcat/sort of the bowtie2 TSV failed"; exit 1; }
BT2N=$(wc -l < /tmp/bt2.tsv)
echo "bowtie2_hiq_records	$BT2N"

# ---------------------------------------------------------------- collapse to one line per name
# The bowtie2 TSV records QNAME/RNAME/POS/MAPQ but NOT the FLAG, so R1 and R2 of a pair are
# indistinguishable by name alone. Collapsing each name to its position LIST (already sorted
# by position above) makes the comparison mate-order independent, which is correct rather than
# a workaround: what is being asserted is that both tools placed this pair in the same two
# places, not which mate went where. Streaming, so memory is O(1) regardless of 40M rows.
collapse() {
  awk -F'\t' '{ k=$1; v=$2":"$3;
      if (k!=p) { if (p!="") print p"\t"n"\t"s; p=k; s=v; n=1 }
      else { s=s","v; n++ } }
    END{ if (p!="") print p"\t"n"\t"s }' "$1"
}
collapse /tmp/bwa.tsv > /tmp/bwa.col
collapse /tmp/bt2.tsv > /tmp/bt2.col
echo "bwa_hiq_names	$(wc -l < /tmp/bwa.col)"
echo "bowtie2_hiq_names	$(wc -l < /tmp/bt2.col)"

# ---------------------------------------------------------------- compare
join -t$'\t' -j1 /tmp/bwa.col /tmp/bt2.col > /tmp/joined.tsv
test "$?" = "0" || { echo "FAIL: join failed"; exit 1; }
echo "names_in_both	$(wc -l < /tmp/joined.tsv)"

# THE METRIC, RESTRUCTURED AFTER THE FIRST RUN MEASURED IT WRONG.
#
# The first attempt asserted position agreement within 5 bp and got 0.980528 against a 0.98
# floor -- a 0.05% margin, i.e. a check that passes today and fails on noise. The breakdown
# said why: 6,457 chromosome disagreements against 382,487 positional ones. Under --local, SAM
# POS is the leftmost ALIGNED base, so when bowtie2 soft-clips a different number of bases than
# bwa the POS shifts even though both tools agree entirely about where the read belongs. A 5 bp
# tolerance on soft-clipped alignments measures clipping convention, not placement -- the
# method-difference trap in practices/cross-checks.md.
#
# So: ASSERT the clip-invariant claim (same chromosome) and REPORT position agreement as a
# CURVE over tolerances. If the positional residual is soft-clipping it rises steeply and
# plateaus; genuine mismapping would stay flat. One tolerance cannot distinguish those.
awk -F'\t' '
  { # $1 name | $2 bwa n | $3 bwa list | $4 bt2 n | $5 bt2 list
    if ($2 != $4) { card++; next }
    comparable++;
    na = split($3, a, ","); split($5, b, ",");
    badchrom = 0; maxd = 0;
    for (i = 1; i <= na; i++) {
      split(a[i], x, ":"); split(b[i], y, ":");
      if (x[1] != y[1]) { badchrom = 1; break }
      d = x[2] - y[2]; if (d < 0) d = -d;
      if (d > maxd) maxd = d;
    }
    if (badchrom) { chrom++; next }
    samechrom++;
    if (maxd == 0)    t0++;
    if (maxd <= 5)    t5++;
    if (maxd <= 10)   t10++;
    if (maxd <= 20)   t20++;
    if (maxd <= 50)   t50++;
    if (maxd <= 100)  t100++;
    if (maxd <= 1000) t1000++;
    if (maxd == 0) h0++; else if (maxd <= 10) h10++; else if (maxd <= 100) h100++;
    else if (maxd <= 1000) h1k++; else hbig++;
  }
  END{
    printf "cardinality_mismatch\t%d\n", card+0;
    printf "names_compared\t%d\n", comparable+0;
    printf "discordant_chrom\t%d\n", chrom+0;
    printf "same_chrom\t%d\n", samechrom+0;
    if (comparable>0) {
      printf "chrom_concordance\t%.6f\n", samechrom/comparable;
      printf "pos_within_0\t%.6f\n",    t0/comparable;
      printf "pos_within_5\t%.6f\n",    t5/comparable;
      printf "pos_within_10\t%.6f\n",   t10/comparable;
      printf "pos_within_20\t%.6f\n",   t20/comparable;
      printf "pos_within_50\t%.6f\n",   t50/comparable;
      printf "pos_within_100\t%.6f\n",  t100/comparable;
      printf "pos_within_1000\t%.6f\n", t1000/comparable;
    }
    printf "resid_0\t%d\n", h0+0;
    printf "resid_1_10\t%d\n", h10+0;
    printf "resid_11_100\t%d\n", h100+0;
    printf "resid_101_1000\t%d\n", h1k+0;
    printf "resid_over_1000\t%d\n", hbig+0;
  }' /tmp/joined.tsv | tee /tmp/concordance.tsv

CHROMC=$(awk -F'\t' '$1=="chrom_concordance"{print $2}' /tmp/concordance.tsv)
COMP=$(awk -F'\t' '$1=="names_compared"{print $2}' /tmp/concordance.tsv)
printf 'chrom_concordance_reported\t%s\n' "$CHROMC"

# ASSERTED: same chromosome among mutually-confident reads. Chromosome assignment does not
# depend on soft-clipping, so this measures placement rather than clipping convention. The
# first run observed 0.999677, so a 0.999 floor has real headroom -- unlike the 0.05% margin
# of the 5 bp position check it replaces.
awk -v c="$CHROMC" 'BEGIN{ if (c+0 < 0.999) { print "FAIL: chromosome concordance " c " below the 0.999 floor"; exit 1 } }' || exit 1

# Vacuity guard -- and this time a GUARD, not a second assertion on the data. The first version
# used 20,000,000, a round number picked without computing the comparable set; it turned out to
# be 19,974,019 and killed a valid run by 0.13%. 10M is unambiguously "enough to mean
# something" while being nowhere near the observed value.
test "$COMP" -gt 10000000 || { echo "FAIL: only $COMP names compared; too few to mean anything"; exit 1; }

{ echo -e "observable\tvalue"
  echo -e "bwa_primary\t$BWAPRIM"
  echo -e "bwa_hiq_records\t$BWAN"
  echo -e "bowtie2_hiq_records\t$BT2N"
  cat /tmp/concordance.tsv
} > /tmp/crosscheck.tsv

df -k /tmp | awk 'NR==2{printf "tmpfs_used_mib\t%.0f\n", $3/1024}'
echo "CROSSCHECK OK"
